<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreAmendment {
 public static function save(PDO $db,array $actor,int $item,array $in):void{
  StoreAccess::require($db,$actor,'orders');$reason=Security::text($in,'reason',2000);$values=$in['custom']??[];if(!is_array($values))throw new HttpError(422,'اطلاعات اصلاحی معتبر نیست.');
  Db::transaction($db,function()use($db,$actor,$item,$in,$values,$reason){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$item])->fetch();$i=StoreAccess::item($db,$item,$actor);if((int)($in['revision']??-1)!==(int)$i['revision'])throw new HttpError(409,'نسخه ردیف تغییر کرده است.');if(in_array($i['status'],['shipped','completed','cancelled','returned'],true))throw new HttpError(422,'قلم تحویل‌شده یا بسته‌شده قابل بازنویسی نیست.');$before=Protocol::decode($i['snapshot']);$form=$before['form']['form'];$nonFiles=array_values(array_filter($form['fields'],fn($f)=>!in_array($f['type'],['file','image'],true)));$allowed=array_column($nonFiles,'key');if(array_diff(array_keys($values),$allowed))throw new HttpError(422,'فقط مقادیر مجاز همین فرم قابل اصلاح‌اند.');$merged=array_replace($before['form']['values'],$values);$validated=StoreForms::validate($db,['id'=>$form['id'],'revision'=>$form['revision'],'fields'=>$nonFiles],$merged,'');if((int)$validated['surcharge']!==(int)$before['form']['surcharge'])throw new HttpError(422,'تغییر مالی پس از پرداخت نیازمند سفارش یا استعلام مالی مستقل است؛ فاکتور قبلی بازنویسی نمی‌شود.');$after=$before;$after['form']['values']=array_replace($before['form']['values'],$validated['values']);$after['amended_at']=date(DATE_ATOM);Db::query($db,"UPDATE store_item_details SET snapshot=?,status=CASE WHEN status='ready' THEN 'designing' ELSE status END,digital_state='pending',approved_proof_id=NULL,revision=revision+1,updated_at=? WHERE item_id=?",[Protocol::encode($after),date(DATE_ATOM),$item]);StoreAccess::audit($db,$actor,'item.amend','item',$item,$before,$after,$reason);StoreOps::history($db,$actor,$i,$i['status'],$reason);StoreOps::notify($db,StoreOps::owner($db,(int)$i['order_id']),(int)$i['order_id'],'amend-'.$item.'-'.($i['revision']+1),'اصلاح اطلاعات اختصاصی با ثبت سابقه انجام شد.');});
 }
